contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function that drives the contract and checks the property
    function run(address payable caller, uint newMin) public {
        // Precondition: use provided caller only to interact via c; ensure caller is non-zero
        require(caller != address(0));

        // 1) initialize the contract so that in the original SetMinSum would be blocked
        c.SetLogFile(address(0));
        c.Initialized();

        // 2) read the current MinSum
        uint before = c.MinSum();

        // 3) attempt to set MinSum to newMin
        // This is the deciding call: in P it should revert and thus not change MinSum; in M it will succeed
        // We make the call; if it reverts, the transaction will revert and the assert won't be reached —
        // therefore we use low-level call to capture success/failure as a boolean without reverting the test
        (bool ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", newMin));

        // 4) observe MinSum after the call
        uint after = c.MinSum();

        // If the original contract enforces the guard, then either the call failed (ok==false) or
        // it succeeded but must not have changed MinSum (after == before). The mutant removes the guard
        // allowing the call to succeed and change MinSum (ok==true and after == newMin != before).

        // The distinguishing invariant: after the attempted SetMinSum, either the call failed or MinSum stayed equal to its previous value.
        assert(!ok || after == before);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint am_collect, uint sent) public payable {
        require(address(this).balance >= sent);
        // Preconditions to reach Collect branch: the holder must have balance >= MinSum and >= am_collect and timestamp > unlockTime.
        // We cannot directly set internal Acc mapping here, but we can emulate by first calling Put to deposit funds and set unlockTime in the past by using 0 lock time and relying on block timestamp ordering.
        // Deposit funds from this contract to set balance for caller via fallback is not possible; instead we use the test contract as the caller to interact with c.
        // Step 1: set MinSum to 0 (allowed before Initialized) so Put succeeds to create balance
        c.SetMinSum(0);
        // Step 2: ensure Initialized is called so original contract will block future SetMinSum
        c.Initialized();
        // Step 3: deposit funds so that Collect can proceed: send Ether with Put via fallback (call Put by sending to fallback which calls Put(0))
        // Call Put by sending value to c (fallback calls Put(0)). Use send amount 'sent'.
        (bool ok,) = address(c).call{value: sent}("");
        // Now call Collect which in original should only allow collection if acc.balance >= MinSum (which is current MinSum)
        // The key invariant: After Initialized(), MinSum must remain unchanged by SetMinSum, so performing Collect cannot observe a smaller MinSum set after initialization.
        // We perform Collect to trigger behavior; the asserted property will relate MinSum before and after an attempted SetMinSum.
        uint before = c.MinSum();
        // Attempt to change MinSum after initialization
        // This call should revert on original if it contains the guard; in mutant it will succeed and change MinSum.
        bool reverted;
        try c.SetMinSum(am_collect) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint after = c.MinSum();
        // General rule: if SetMinSum was reverted then MinSum must be unchanged; equivalently, if Initialized() was called (we did call it), then either SetMinSum reverted or MinSum remains equal to before.
        // Express as: reverted || after == before
        assert(reverted || after == before);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive c to detect missing lock: attempt reentrancy via a malicious contract
    // Parameters:
    //  initVal - value to set initially (unused by logic but part of signature)
    //  reentrantAddr - address of a helper contract that will try to call back into c.SetMinSum
    function run(uint initVal, address payable reentrantAddr) public {
        // Preconditions: reentrantAddr must be a contract that, when triggered,
        // calls back into c.SetMinSum. We just invoke it to cause that reentry.
        // First, ensure c is initialized to unlocked state by calling Initialized()
        c.Initialized();

        // Now perform a normal external call that will invoke the external helper
        // The helper is expected to call c.SetMinSum during its execution to attempt reentry.
        // We perform the call by sending zero value to the helper address.
        // Use a low-level call so we can observe whether it succeeded.
        (bool ok, ) = reentrantAddr.call(abi.encodeWithSignature("trigger(address,uint256)", address(c), initVal));

        // The property: SetMinSum must not have been successfully executed twice via reentrancy.
        // We check that calling SetMinSum now either reverts (if it was locked during helper) or
        // cannot have been executed twice. Since we cannot directly count executions, we rely
        // on the fact that in the correct contract the helper's attempt to call SetMinSum
        // reentrantly would have reverted, making ok == false. In the mutant missing the lock,
        // the reentrant call would succeed and ok would be true.
        // Thus assert that ok is false.
        assert(!ok);
    }

    // fallback and receive to allow interactions if needed
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt a Collect call and then assert that MinSum did not change as a result.
    // The test is general: for any caller-supplied collectAmount, calling c.Collect(collectAmount)
    // must leave c.MinSum() equal to the value observed before the call.
    function run(uint collectAmount) public payable {
        // No extra precondition required for the original guarded contract.
        uint minBefore = c.MinSum();
        c.Collect(collectAmount);
        uint minAfter = c.MinSum();
        assert(minAfter == minBefore);
    }

    // No receive logic is needed for this test.
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We'll require that the contract has been initialized (so SetMinSum cannot be called after initialization in original),
    // and that caller has sufficient balance in c to trigger the Collect branch if needed.
    // To observe the difference caused by a broken nonReentrant_ (which allows reentrant SetMinSum to run during Collect),
    // we require that intialized has been set (so SetMinSum would revert if called), and then assert MinSum unchanged.

    function run(uint _am) public payable {
        // require that this test can send any Ether if needed (not used here), and that contract has been initialized
        // We cannot read internal 'intitalized', so instead require that calling Initialized() earlier would have been possible.
        // But we must restrict inputs: require true to satisfy template if no precondition needed. However original needs initialization to block SetMinSum.
        // We therefore require that c.MinSum() is some current value and we'll assert it doesn't change after Collect.
        require(true);

        uint before = c.MinSum();
        // Call Collect with amount parameter; the original contract's reentrancy guard prevents modification of MinSum during Collect,
        // so MinSum must remain equal to 'before' after the call for all inputs. The mutant allows reentrant SetMinSum to run and may change it.
        c.Collect(_am);
        uint after = c.MinSum();
        assert(after == before);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We will call Collect and then assert MinSum unchanged.
    function run(uint lockAmount, uint collectAmount, uint minSumVal) public payable {
        // Preconditions to reach the relevant behavior in P:
        // 1) Ensure this test contract has enough Ether to call Put/Collect when needed.
        require(address(this).balance >= lockAmount + 1 ether || lockAmount == 0, "insufficient balance");
        // 2) Initialize C: set MinSum and mark initialized so SetMinSum cannot be called later.
        // Note: SetMinSum and Initialized are nonReentrant_; calling them from here is fine.
        c.SetMinSum(minSumVal);
        c.Initialized();

        // Record MinSum before calling Collect
        uint before = c.MinSum();

        // Call Collect as in the counterexample (this is the action that differs under mutant)
        // Send any required Ether from this contract if collectAmount > 0
        if (collectAmount > 0) {
            // ensure we have Ether to forward
            require(address(this).balance >= collectAmount, "not enough Ether to call Collect");
            c.Collect{value: collectAmount}(collectAmount);
        } else {
            c.Collect(collectAmount);
        }

        // Assert that MinSum remained the same (general property: Collect must not change MinSum once initialized)
        assert(c.MinSum() == before);
    }

    // Allow this contract to receive Ether so it can forward funds in tests
    receive() external payable { }
}

