contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        // Deploy attacker pointing at c; attacker will attempt to re-enter Collect and then call SetMinSum
        attacker = new Attacker(address(c));
    }

    // fuzzed params: amount to deposit and a candidate newMin to set during reentrancy
    function testFuzz_property(uint256 deposit, uint256 newMin) public {
        // keep deposit sensible but wide
        deposit = bound(deposit, 1, 1 ether);
        // fund attacker EOA so it can forward value
        vm.deal(address(this), 2 ether);

        // Set up: give attacker contract some ETH to call Put
        vm.deal(address(attacker), deposit + 1 ether);

        // Ensure contract has a baseline MinSum
        uint256 origMin = 123;
        c.SetMinSum(origMin);

        // Configure attacker with the candidate newMin it will try to set during reentrancy
        attacker.configure(newMin);

        // Attacker will call Put to deposit and set up balance so Collect can be invoked. Use prank from attacker.
        // First, attacker deposits by calling Put via its own payable call which will store balance and record unlockTime = now
        vm.prank(address(attacker));
        c.Put{value: deposit}(0);

        // Now attempt to trigger Collect from attacker which will cause the contract to call back into attacker (log AddMessage uses external call to Log but here attacker will be the msg.sender in Collect)
        // We'll have attacker call Collect on its own holder; attacker.receive will re-enter into c.SetMinSum(newMin) during the external call if mutant allows reentrancy.
        bool ok;
        try c.Collect{value: 0}(1) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property to assert: after Collect, MinSum must remain equal to origMin for the correct contract.
        // The buggy mutant allows re-entrancy that can change MinSum to newMin for some inputs; thus this assertion will fail on the mutant for some fuzz values.
        assertTrue(c.MinSum() == origMin);
    }
}

// Minimal adversarial re-entrant helper: when it receives ETH (via the external call from Collect), it will re-enter C and call SetMinSum with the configured value.
contract Attacker {
    address public target;
    uint256 public toSet;
    bool public configured;

    constructor(address _target) {
        target = _target;
    }

    function configure(uint256 _v) external {
        toSet = _v;
        configured = true;
    }

    // fallback/receive will be invoked when C does an external call to msg.sender during Collect (e.g., via call{})
    receive() external payable {
        if (configured) {
            // try to call SetMinSum during re-entrancy
            // ignore errors
            (bool s, ) = target.call(abi.encodeWithSignature("SetMinSum(uint256)", toSet));
            s;
        }
    }
}

